"""Preflight legacy relational data and close reverse ownership/issuer invariants.

This migration deliberately aborts on inconsistent legacy rows, without trying
to rewrite historical ownership or audit provenance.
"""
from django.db import migrations

PREFLIGHT_SQL="-- Upgrade preflight intentionally fails closed on any legacy invalid relation.\n-- A single transaction holds write-excluding table locks until validation AND\n-- trigger installation complete; no invalid row can race between the two.\nLOCK TABLE public.accounts_membership,\n           public.onboarding_onboardingcase,\n           public.onboarding_caseassignment IN SHARE ROW EXCLUSIVE MODE;\n\nDO $m1_check$\nBEGIN\n IF EXISTS (\n   SELECT 1 FROM public.onboarding_onboardingcase c\n   LEFT JOIN public.accounts_membership m ON m.id=c.employee_id\n   WHERE m.id IS NULL OR m.organization_id IS DISTINCT FROM c.organization_id\n      OR m.role IS DISTINCT FROM 'EMPLOYEE'\n ) THEN RAISE EXCEPTION 'M1 migration blocked: invalid legacy case employee/org/role' USING ERRCODE='23514'; END IF;\n IF EXISTS (\n   SELECT 1 FROM public.onboarding_caseassignment a\n   JOIN public.onboarding_onboardingcase c ON c.id=a.case_id\n   LEFT JOIN public.accounts_membership m ON m.id=a.member_id\n   LEFT JOIN public.accounts_membership issuer ON issuer.id=a.assigned_by_id\n   WHERE m.id IS NULL OR m.organization_id IS DISTINCT FROM c.organization_id\n      OR m.role IS DISTINCT FROM a.role\n      OR a.role NOT IN ('HR','IT','MANAGER')\n      OR (a.assigned_by_id IS NOT NULL AND\n          issuer.organization_id IS DISTINCT FROM c.organization_id)\n      OR a.effective_from > clock_timestamp()\n ) THEN RAISE EXCEPTION 'M1 migration blocked: invalid legacy assignment/issuer relationship' USING ERRCODE='23514'; END IF;\nEND $m1_check$;\n"
GUARD_SQL="-- M1 CREATED-only roots are immutable; subsequent lifecycle migration must\n-- explicitly preserve relational authority if root transfer is ever supported.\nCREATE OR REPLACE FUNCTION public.m1_deny_case_root_reparent()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n IF (NEW.organization_id,NEW.employee_id)\n    IS DISTINCT FROM (OLD.organization_id,OLD.employee_id) THEN\n   RAISE EXCEPTION 'Case employee and organization are immutable in M1'\n       USING ERRCODE='23514';\n END IF;\n RETURN NEW;\nEND; $$;\nCREATE TRIGGER m1_case_root_immutable\n BEFORE UPDATE OF organization_id,employee_id ON public.onboarding_onboardingcase\n FOR EACH ROW EXECUTE FUNCTION public.m1_deny_case_root_reparent();\n\nCREATE OR REPLACE FUNCTION public.m1_validate_member_change()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n IF (NEW.organization_id,NEW.role,NEW.user_id)\n    IS DISTINCT FROM (OLD.organization_id,OLD.role,OLD.user_id) THEN\n   IF EXISTS (SELECT 1 FROM public.onboarding_onboardingcase WHERE employee_id=NEW.id)\n      OR EXISTS (SELECT 1 FROM public.onboarding_caseassignment WHERE member_id=NEW.id)\n      OR EXISTS (SELECT 1 FROM public.onboarding_caseassignment WHERE assigned_by_id=NEW.id) THEN\n     RAISE EXCEPTION 'Cannot change referenced membership identity, role or organization'\n       USING ERRCODE='23514';\n   END IF;\n END IF;\n RETURN NEW;\nEND; $$;\n"
REVERSE_SQL="DROP TRIGGER IF EXISTS m1_case_root_immutable ON public.onboarding_onboardingcase;\nDROP FUNCTION IF EXISTS public.m1_deny_case_root_reparent();\nCREATE OR REPLACE FUNCTION public.m1_validate_member_change()\nRETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$\nBEGIN\n IF (NEW.organization_id,NEW.role,NEW.user_id)\n    IS DISTINCT FROM (OLD.organization_id,OLD.role,OLD.user_id) THEN\n   IF EXISTS (SELECT 1 FROM public.onboarding_onboardingcase WHERE employee_id=NEW.id)\n      OR EXISTS (SELECT 1 FROM public.onboarding_caseassignment WHERE member_id=NEW.id) THEN\n     RAISE EXCEPTION 'Cannot modify identity/role/organization of referenced membership'\n       USING ERRCODE='23514';\n   END IF;\n END IF;\n RETURN NEW;\nEND; $$;\n"

class Migration(migrations.Migration):
    dependencies=[('onboarding','0003_member_identity_guard')]
    operations=[
        migrations.RunSQL(PREFLIGHT_SQL,migrations.RunSQL.noop),
        migrations.RunSQL(GUARD_SQL,REVERSE_SQL),
    ]
